// User-review audio generated by the same synthesizer as the App. No recording.
import fs from 'node:fs';
import {Tone} from '../apps/palm-notes/src/tone.mjs';
const config=JSON.parse(fs.readFileSync(new URL('../apps/palm-notes/src/instrument.json',import.meta.url)));
const rate=48000, chunks=[], sections=[];let frames=0;
for(const voice of config.voices) {
  sections.push({voice:voice.name,start:frames/rate});
  const synth=new Tone(rate,config.sound,config.voices);
  for(const [id,seconds] of [[1,1.2],[3,.4],[5,.4],[6,.4],[7,.4],[5,.6]]) {
    synth.set({frequency:config.notes.find(n=>n.id===id).frequency,voice:voice.id,leaseMs:seconds*1000,level:.7});
    const signal=new Float32Array(Math.round((seconds+.12)*rate));synth.render(signal);chunks.push(signal);frames+=signal.length;
  }
  chunks.push(new Float32Array(rate*.5));frames+=rate*.5;
}
const wav=Buffer.alloc(44+frames*2);wav.write('RIFF');wav.writeUInt32LE(wav.length-8,4);wav.write('WAVEfmt ',8);wav.writeUInt32LE(16,16);wav.writeUInt16LE(1,20);wav.writeUInt16LE(1,22);wav.writeUInt32LE(rate,24);wav.writeUInt32LE(rate*2,28);wav.writeUInt16LE(2,32);wav.writeUInt16LE(16,34);wav.write('data',36);wav.writeUInt32LE(frames*2,40);
let offset=44;for(const chunk of chunks)for(const sample of chunk){wav.writeInt16LE(Math.round(Math.max(-1,Math.min(1,sample))*32767),offset);offset+=2;}
const output='/tmp/palm-notes/PalmNotes-four-tones.wav';fs.writeFileSync(output,wav);
console.log(JSON.stringify({output,duration:frames/rate,sections}));
